-- FU/be-seed (UNI-2634): dạng bài "Hoàn thành câu" của phần Tiếng Anh HSA
-- (đề test giả định mục 2.1). Nhóm Hoàn thành câu dùng dạng bài này thay vì chia 12/12/11.
INSERT INTO catalog.catalog_item (id, group_id, code, code_normalized, value, name_vi, name_en, description, display_order, status, is_system, parent_id, depth, path)
SELECT '5b100b3c-4336-51b7-8277-3cc4223367ae', '00000000-0000-7000-8100-000000000006', 'SENTENCE_COMPLETION', 'sentence_completion',
       GREATEST(9, g.last_value + 1, COALESCE((SELECT MAX(value) + 1 FROM catalog.catalog_item WHERE group_id = g.id), 1)),
       'Hoàn thành câu', 'Sentence completion', '[MẪU] Dạng bài hoàn thành câu (HSA Tiếng Anh)', 8, 1, false, NULL, 1, '/5b100b3c-4336-51b7-8277-3cc4223367ae/'
FROM catalog.catalog_group g WHERE g.id = '00000000-0000-7000-8100-000000000006'
ON CONFLICT (group_id, code_normalized) DO NOTHING;

UPDATE catalog.catalog_group g SET last_value = GREATEST(g.last_value, COALESCE((SELECT MAX(value) FROM catalog.catalog_item WHERE group_id = g.id), 0)) WHERE g.id = '00000000-0000-7000-8100-000000000006';

